<?php
namespace App\Services\Reconciliation\Governance;
use App\Enums\ReconciliationStatus;use App\Models\BankTransaction;use App\Models\FinancialDocument;use App\Models\Reconciliation;use App\Services\Audit\AuditService;use App\Services\Reconciliation\ReconciliationWriter;use Illuminate\Support\Facades\DB;
final class GovernedReconciliationService {public function __construct(private ApprovalPolicy $policy,private ReconciliationWriter $writer,private AuditService $audit){}
 public function reconcile(BankTransaction $tx,FinancialDocument $doc,float $score,string $userId,string $method='manual',?string $ruleId=null):Reconciliation{$amount=min(abs((float)$tx->amount),(float)$doc->open_amount);$decision=$this->policy->evaluate($tx->organization_id,$amount,$method,false);if(!$decision['requires_checker']){return $this->writer->approve($tx,$doc,$score,$userId,$method,$ruleId);}
  return DB::transaction(function()use($tx,$doc,$score,$userId,$method,$ruleId,$amount,$decision){$lockedTx=BankTransaction::query()->lockForUpdate()->findOrFail($tx->id);$lockedDoc=FinancialDocument::query()->lockForUpdate()->findOrFail($doc->id);$apply=min(abs((float)$lockedTx->amount),(float)$lockedDoc->open_amount);$r=Reconciliation::create(['organization_id'=>$lockedTx->organization_id,'status'=>ReconciliationStatus::PendingReview,'method'=>$method,'confidence_score'=>$score,'proposed_by'=>$userId,'total_amount'=>$apply,'risk_level'=>$decision['risk_level'],'requires_checker'=>true]);$r->items()->create(['bank_transaction_id'=>$lockedTx->id,'financial_document_id'=>$lockedDoc->id,'applied_amount'=>$apply,'currency'=>$lockedTx->currency]);$this->audit->record('reconciliation.proposed',$r,null,$r->toArray(),['rule_id'=>$ruleId,'requires_checker'=>true]);return $r;});}}
